const q8 = (v) => Number((parseFloat(v) || 0).toFixed(8));
const costingMethod = {{node:code_node_wBfvXM2G.data.costingMethod}};
const fifoData = {{node:search_node_NCi8U4My.data.data}};
const waData = {{node:search_node_7bvv7f8g.data.data}};
